from __future__ import annotations

from html import escape
from typing import Any, Mapping


def _e(value: Any) -> str:
    return escape(str(value if value is not None else ""), quote=True)


_STYLE = r"""
:root{color-scheme:light;--ink:#172033;--muted:#667085;--line:#dbe2ee;--panel:#fff;--soft:#f4f7fb;--brand:#2457d6;--alert:#b42318;--high:#9a4d00;--medium:#176b4c;--low:#667085}*{box-sizing:border-box}body{margin:0;background:#eef2f8;color:var(--ink);font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","Noto Sans TC","PingFang TC",sans-serif;line-height:1.55}a{color:var(--brand);text-underline-offset:.16em}.hero{background:linear-gradient(135deg,#10275f,#244fc1 55%,#6f42c1);color:#fff;padding:30px max(18px,calc((100vw - 1220px)/2))}.hero h1{margin:0;font-size:clamp(1.8rem,4vw,3rem)}.hero p{margin:8px 0 0}.shell{width:min(1220px,calc(100% - 24px));margin:20px auto 60px}.notice{padding:14px 16px;background:#fff8db;border:1px solid #ecd887;border-radius:12px;color:#5d4a00}.summary-grid{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:8px;margin:14px 0}.metric{background:#fff;border:1px solid var(--line);border-radius:12px;padding:11px 13px}.metric strong{display:block;font-size:1.3rem}.metric span{font-size:.76rem;color:var(--muted)}.toolbar{display:grid;grid-template-columns:minmax(260px,2fr) repeat(5,minmax(145px,1fr));gap:10px;padding:14px;background:#fff;border:1px solid var(--line);border-radius:14px;position:sticky;top:0;z-index:10;box-shadow:0 8px 24px rgba(24,37,68,.08)}.field{display:grid;gap:5px}.field label{font-size:.75rem;color:var(--muted);font-weight:750}.field input,.field select{min-height:40px;border:1px solid #bfc9d9;border-radius:9px;background:#fff;padding:7px 9px}.wide{grid-column:span 2}.actions{grid-column:1/-1;display:flex;gap:8px;align-items:center;flex-wrap:wrap}.btn{border:1px solid #bfc9d9;background:#fff;border-radius:9px;min-height:36px;padding:6px 10px;cursor:pointer}.btn.primary{background:var(--brand);color:#fff;border-color:var(--brand)}.result-bar,.pager{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin:14px 2px}.downloads{display:flex;gap:10px;flex-wrap:wrap;font-size:.84rem}.paper-list{display:grid;gap:10px}.paper{background:#fff;border:1px solid var(--line);border-radius:14px;padding:16px;box-shadow:0 8px 24px rgba(24,37,68,.06)}.paper h2{font-size:1.08rem;line-height:1.4;margin:0}.original{color:var(--muted);font-size:.87rem;margin:6px 0 0}.badges{display:flex;gap:6px;flex-wrap:wrap;margin:10px 0}.badge{display:inline-flex;padding:2px 8px;border-radius:999px;background:#edf2ff;color:#2346a5;font-size:.74rem;font-weight:750}.badge.ALERT{background:#ffebe9;color:var(--alert)}.badge.HIGH{background:#fff1dc;color:var(--high)}.badge.MEDIUM{background:#e9f6f1;color:var(--medium)}.badge.LOW{background:#eef2f6;color:var(--low)}.badge.projected{background:#e8f1ff;color:#174ea6}.triage-box{background:var(--soft);border-left:4px solid var(--brand);border-radius:8px;padding:10px 12px;font-size:.88rem}.reasons{color:var(--muted);font-size:.78rem;margin-top:6px}.meta{display:flex;gap:8px 14px;flex-wrap:wrap;margin-top:10px;color:var(--muted);font-size:.82rem}.ids,.links{display:flex;gap:7px;flex-wrap:wrap;margin-top:10px}.ids a,.ids span,.links a{font-size:.78rem;border:1px solid #ccd5e3;background:#fff;border-radius:7px;padding:4px 7px;text-decoration:none}.empty{display:none;text-align:center;padding:28px;background:#fff;border:1px dashed #aeb9ca;border-radius:12px;color:var(--muted)}.empty.visible{display:block}.small{font-size:.78rem;color:var(--muted)}footer{text-align:center;padding:20px;color:var(--muted);font-size:.78rem}@media(max-width:1050px){.toolbar{position:static;grid-template-columns:1fr 1fr 1fr}.wide{grid-column:1/-1}.summary-grid{grid-template-columns:repeat(3,1fr)}}@media(max-width:650px){.toolbar{grid-template-columns:1fr}.wide{grid-column:1}.summary-grid{grid-template-columns:1fr 1fr}}
"""

_SCRIPT = r"""
(() => {
 const esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]));
 const norm=v=>String(v||'').normalize('NFKC').toLocaleLowerCase('zh-Hant');
 const q=document.querySelector('#q'),tier=document.querySelector('#tier'),klass=document.querySelector('#klass'),rec=document.querySelector('#rec'),journal=document.querySelector('#journal'),category=document.querySelector('#category'),projected=document.querySelector('#projected'),sort=document.querySelector('#sort'),size=document.querySelector('#size'),list=document.querySelector('#list'),matched=document.querySelector('#matched'),pageLabel=document.querySelector('#page-label'),prev=document.querySelector('#prev'),next=document.querySelector('#next'),empty=document.querySelector('#empty'),reset=document.querySelector('#reset'),showAll=document.querySelector('#show-all');
 let data=null,filtered=[],page=1;
 const tierRank={ALERT:0,HIGH:1,MEDIUM:2,LOW:3};
 const tierLabel={ALERT:'警示',HIGH:'優先',MEDIUM:'一般候選',LOW:'低優先／背景'};
 const recLabel={VERIFY_IMMEDIATELY:'立即核對',FETCH_PRIORITY:'優先抓摘要／全文',FETCH_IF_CAPACITY:'有餘裕再抓',METADATA_ONLY:'先停在 metadata'};
 const links=a=>[a.doi?`<a href="https://doi.org/${esc(a.doi)}">DOI</a>`:'',a.pmid?`<a href="https://pubmed.ncbi.nlm.nih.gov/${esc(a.pmid)}/">PMID</a>`:'',a.pmcid?`<a href="https://pmc.ncbi.nlm.nih.gov/articles/${esc(a.pmcid)}/">PMCID</a>`:''].filter(Boolean).join('');
 const card=a=>{const t=a.metadata_triage||{},title=a.title_zh_tw||a.title_original,authors=(a.authors||[]).join('、'),cats=(a.categories||[]).join('、');return `<article class="paper"><h2>${esc(title)}</h2>${a.title_zh_tw?`<p class="original"><strong>原文題名：</strong>${esc(a.title_original)}</p>`:''}<div class="badges"><span class="badge ${esc(t.tier)}">${esc(tierLabel[t.tier]||t.tier)}</span><span class="badge">${esc(t.label_zh_tw||t.attention_class)}</span>${a.default_projected?'<span class="badge projected">預設投影</span>':''}<span class="badge">${esc(a.processing_mode)}</span><span class="badge">${esc(a.curation_role)}</span></div><div class="triage-box"><strong>${esc(recLabel[t.fetch_recommendation]||t.fetch_recommendation)}</strong><div>依題名與書目 metadata 分流；仍須摘要或全文才能判斷科學內容。</div><div class="reasons">理由碼：${esc((t.reason_codes||[]).join(' · '))}</div></div><div class="meta"><span>${esc(a.journal)}</span><span>${esc(a.publication_date||'')}</span><span>${esc(authors||'作者未列出')}</span><span>${esc(cats||'未分類')}</span></div><div class="ids">${links(a)||'<span>無標準識別碼</span>'}</div><div class="links"><a href="../${esc(a.url)}">開啟期刊 triage 頁</a></div></article>`};
 function apply(resetPage=true){if(!data)return;const needle=norm(q.value).trim();filtered=(data.articles||[]).filter(a=>{const t=a.metadata_triage||{},priority=tier.value==='priority'?['ALERT','HIGH'].includes(t.tier):!tier.value||t.tier===tier.value;return priority&&(!needle||norm([a.title_zh_tw,a.title_original,(a.authors||[]).join(' '),a.doi,a.pmid,a.pmcid,a.journal,a.journal_slug,(t.reason_codes||[]).join(' ')].join(' ')).includes(needle))&&(!klass.value||t.attention_class===klass.value)&&(!rec.value||t.fetch_recommendation===rec.value)&&(!journal.value||a.journal_slug===journal.value)&&(!category.value||(a.categories||[]).includes(category.value))&&(!projected.value||(projected.value==='yes'&&a.default_projected)||(projected.value==='no'&&!a.default_projected))});filtered.sort((a,b)=>sort.value==='newest'?String(b.publication_date).localeCompare(String(a.publication_date)):sort.value==='journal'?String(a.journal).localeCompare(String(b.journal),'zh-Hant')||Number(a.global_triage_rank)-Number(b.global_triage_rank):sort.value==='title'?String(a.title_zh_tw||a.title_original).localeCompare(String(b.title_zh_tw||b.title_original),'zh-Hant'):Number(a.global_triage_rank)-Number(b.global_triage_rank));if(resetPage)page=1;render();}
 function render(){const n=Number(size.value)||50,pages=Math.max(1,Math.ceil(filtered.length/n));page=Math.min(page,pages);const start=(page-1)*n,end=Math.min(start+n,filtered.length);list.innerHTML=filtered.slice(start,end).map(card).join('');matched.textContent=String(filtered.length);pageLabel.textContent=filtered.length?`${start+1}–${end} / ${filtered.length} · 第 ${page}/${pages} 頁`:'0 / 0';prev.disabled=page<=1;next.disabled=page>=pages;empty.classList.toggle('visible',filtered.length===0)}
 fetch('../metadata-triage.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw new Error(String(r.status));return r.json()}).then(v=>{data=v;const classes=[...new Set((v.articles||[]).map(a=>a.metadata_triage?.attention_class).filter(Boolean))].sort(),journals=[...new Map((v.articles||[]).map(a=>[a.journal_slug,a.journal])).entries()].sort((a,b)=>String(a[1]).localeCompare(String(b[1]),'zh-Hant')),categories=[...new Set((v.articles||[]).flatMap(a=>a.categories||[]))].sort();klass.innerHTML='<option value="">全部類別</option>'+classes.map(x=>`<option>${esc(x)}</option>`).join('');journal.innerHTML='<option value="">全部期刊</option>'+journals.map(([slug,name])=>`<option value="${esc(slug)}">${esc(name)}</option>`).join('');category.innerHTML='<option value="">全部領域</option>'+categories.map(x=>`<option>${esc(x)}</option>`).join('');tier.value='priority';apply(true)}).catch(()=>document.querySelector('#load-error').hidden=false);
 for(const el of [q,tier,klass,rec,journal,category,projected,sort,size])el.addEventListener(el===q?'input':'change',()=>apply(true));prev.addEventListener('click',()=>{page=Math.max(1,page-1);render()});next.addEventListener('click',()=>{page+=1;render()});reset.addEventListener('click',()=>{q.value='';tier.value='priority';klass.value='';rec.value='';journal.value='';category.value='';projected.value='';sort.value='priority';size.value='50';apply(true)});showAll.addEventListener('click',()=>{tier.value='';apply(true)});
})();
"""


def render_metadata_triage_dashboard(index: Mapping[str, Any]) -> str:
    counts = index.get("canonical_triage_counts") or {}
    tiers = counts.get("by_tier") or {}
    priority_count = int(tiers.get("ALERT", 0)) + int(tiers.get("HIGH", 0))
    return f"""<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="EvidenceRadar Editions metadata triage dashboard"><title>Metadata Triage｜EvidenceRadar Editions</title><style>{_STYLE}</style></head><body><header class="hero"><h1>Metadata Triage</h1><p>先把 4,000+ 筆書目 metadata 分成可解釋候選層級，再決定哪些值得抓摘要或全文。</p></header><main class="shell"><p><a href="../">← 返回 Editions 期刊總表</a></p><p class="notice"><strong>別把這頁當排行榜：</strong>目前只使用題名、article type、DOI／PMID／PMCID 與來源 metadata。`HIGH` 代表「優先進一步讀」，不代表證據較強、結論正確或研究真的新穎。完整 canonical records 沒有刪除。</p><section class="summary-grid"><div class="metric"><strong>{index.get('canonical_article_count',0)}</strong><span>已套規則 canonical records</span></div><div class="metric"><strong>{priority_count}</strong><span>ALERT + HIGH</span></div><div class="metric"><strong>{index.get('default_projected_article_count',0)}</strong><span>預設 browse/search 投影</span></div><div class="metric"><strong>{index.get('default_omitted_article_count',0)}</strong><span>僅從預設 payload 省略</span></div><div class="metric"><strong>{tiers.get('MEDIUM',0)}</strong><span>一般候選</span></div><div class="metric"><strong>{tiers.get('LOW',0)}</strong><span>低優先／背景</span></div></section><section class="toolbar"><div class="field wide"><label for="q">搜尋題名、作者、期刊、識別碼或理由碼</label><input id="q" type="search" placeholder="輸入關鍵字…"></div><div class="field"><label for="tier">Triage tier</label><select id="tier"><option value="priority">ALERT + HIGH</option><option value="">全部層級</option><option>ALERT</option><option>HIGH</option><option>MEDIUM</option><option>LOW</option></select></div><div class="field"><label for="klass">候選類別</label><select id="klass"><option value="">全部類別</option></select></div><div class="field"><label for="rec">後續動作</label><select id="rec"><option value="">全部建議</option><option>VERIFY_IMMEDIATELY</option><option>FETCH_PRIORITY</option><option>FETCH_IF_CAPACITY</option><option>METADATA_ONLY</option></select></div><div class="field"><label for="journal">期刊</label><select id="journal"><option value="">全部期刊</option></select></div><div class="field"><label for="category">領域</label><select id="category"><option value="">全部領域</option></select></div><div class="actions"><div class="field"><label for="projected">預設投影</label><select id="projected"><option value="">全部 records</option><option value="yes">在預設 browse/search</option><option value="no">只在完整 triage/canonical</option></select></div><div class="field"><label for="sort">排序</label><select id="sort"><option value="priority">全域公平 triage</option><option value="newest">日期新到舊</option><option value="journal">期刊</option><option value="title">題名</option></select></div><div class="field"><label for="size">每頁</label><select id="size"><option>25</option><option selected>50</option><option>100</option><option>200</option></select></div><button class="btn" id="show-all" type="button">顯示全部層級</button><button class="btn primary" id="reset" type="button">重設</button></div></section><div class="result-bar"><span>符合條件 <strong id="matched">0</strong> 篇</span><span class="downloads"><a href="../metadata-triage.json">完整 triage JSON</a><a href="../metadata-triage-policy.json">執行規則</a><a href="../search-index.json">預設搜尋 JSON</a></span></div><p id="load-error" class="notice" hidden>metadata-triage.json 載入失敗。</p><section id="list" class="paper-list" aria-live="polite"></section><div id="empty" class="empty">沒有紀錄符合目前篩選。</div><div class="pager"><button class="btn" id="prev" type="button">上一頁</button><strong id="page-label">0 / 0</strong><button class="btn" id="next" type="button">下一頁</button></div><p class="small">Policy：{_e(index.get('policy_id'))}。全域預設排序會在同一 tier 內輪流取不同期刊，避免 megajournal 把第一頁吞光；同一期刊投影亦會壓低近重複題名。</p></main><footer>EvidenceRadar Editions · metadata triage is a fetch queue, not an evidence grade</footer><script>{_SCRIPT}</script></body></html>\n"""
